"""Small exact-answer verifier and DAPO parquet loader."""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path
from collections.abc import Sequence


@dataclass(frozen=True)
class MathExample:
    prompt: str
    answer: str
    index: str = ""


def _extract_boxed(text: str) -> str | None:
    marker = "\\boxed"
    start = text.rfind(marker)
    if start < 0:
        return None
    brace = text.find("{", start + len(marker))
    if brace < 0:
        return None
    depth = 0
    for position in range(brace, len(text)):
        if text[position] == "{":
            depth += 1
        elif text[position] == "}":
            depth -= 1
            if depth == 0:
                return text[brace + 1 : position]
    return None


def extract_answer(text: str) -> str | None:
    """Extract the required final answer without trusting chain-of-thought text.

    Preference order: an explicit ``\\boxed{}`` first, then the last line that
    looks like ``Answer: <value>``. Models wrap answer lines in markdown
    emphasis (``**Answer:** 35``) and sometimes put the value on the next line
    (``Answer:\\n56``); both are handled by scanning lines from the bottom up.
    """

    boxed = _extract_boxed(text)
    if boxed is not None:
        return boxed.strip()
    lines = text.splitlines()
    for i in range(len(lines) - 1, -1, -1):
        stripped = lines[i].strip()
        match = re.match(
            r"\**\s*(?:final\s+)?answer\s*:?\s*(.*)$",
            stripped,
            flags=re.IGNORECASE,
        )
        if not match:
            continue
        value = match.group(1).strip().strip("*_`").strip()
        if value:
            return value
        # "Answer:" with nothing after it — take the next non-empty line.
        for j in range(i + 1, len(lines)):
            nxt = lines[j].strip()
            if nxt:
                return nxt.strip("*_`").strip()
    return None


def _numeric_value(text: str) -> float | None:
    value = text.strip().strip("$").replace(",", "")
    value = value.replace("\\left", "").replace("\\right", "")
    value = value.replace("\\dfrac", "\\frac")
    for _ in range(4):
        updated = re.sub(r"\\frac\s*\{([^{}]+)\}\s*\{([^{}]+)\}", r"(\1)/(\2)", value)
        if updated == value:
            break
        value = updated
    value = value.replace("^", "**")
    try:
        from sympy.parsing.sympy_parser import parse_expr

        expression = parse_expr(value, transformations="all", evaluate=True)
        if getattr(expression, "free_symbols", None):
            return None
        return float(expression.evalf())
    except Exception:
        match = re.fullmatch(r"[-+]?\d+(?:\.\d+)?", value)
        return float(match.group(0)) if match else None


def answers_equal(predicted: str | None, expected: str) -> bool:
    if predicted is None:
        return False
    left = _numeric_value(predicted)
    right = _numeric_value(expected)
    if left is not None and right is not None:
        return abs(left - right) <= 1e-6 * max(1.0, abs(right))
    normalize = lambda text: re.sub(r"\s+", "", text.strip().lower().strip("$"))
    return normalize(predicted) == normalize(expected)


def verify_math(response: str, expected: str) -> float:
    return 1.0 if answers_equal(extract_answer(response), str(expected)) else 0.0


def load_dapo_examples(path: str | Path, limit: int | None = None, seed: int = 7) -> list[MathExample]:
    """Load prompts and numeric ground truth from the DAPO parquet format."""

    import pandas as pd

    frame = pd.read_parquet(path)
    if limit is not None and limit < len(frame):
        frame = frame.sample(n=limit, random_state=seed).reset_index(drop=True)
    examples: list[MathExample] = []
    for row in frame.to_dict(orient="records"):
        prompt_value = row["prompt"]
        if hasattr(prompt_value, "tolist"):
            prompt_value = prompt_value.tolist()
        if isinstance(prompt_value, Sequence) and not isinstance(prompt_value, str):
            prompt = next(item["content"] for item in prompt_value if item.get("role") == "user")
        else:
            prompt = str(prompt_value)
        reward_model = row["reward_model"]
        answer = reward_model.get("ground_truth", "") if isinstance(reward_model, dict) else str(reward_model)
        extra_info = row.get("extra_info", {})
        index = str(extra_info.get("index", "")) if isinstance(extra_info, dict) else ""
        examples.append(MathExample(prompt=prompt, answer=str(answer), index=index))
    if len(examples) < 3:
        raise ValueError("at least three math examples are required")
    return examples

